import { screen } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { renderWithProviders } from "../../tests/utils";
import { ConversationEventType, type ConversationEvent } from "../../types";
import { MemorySetEventInfo } from "./MemorySetEventInfo";

vi.mock("./blocks/DetailView", () => ({
  DetailView: ({ title, children }: { title: string; children: React.ReactNode }) => (
    <div>
      <h1>{title}</h1>
      {children}
    </div>
  ),
}));

const event: ConversationEvent = {
  id: "e1",
  conversationEventType: ConversationEventType.MemorySet,
  name: "card_replace.replacement_reason",
  value: "stolen",
  actionText: "",
  flowId: "",
  stepId: "",
  timestamp: "2020-01-01T00:00:00.000Z",
  originalTimestamp: 0,
  metadata: { parseData: {} },
  __typename: "ConversationEvent",
};

describe("MemorySetEventInfo", () => {
  it("shows name and value", () => {
    renderWithProviders(<MemorySetEventInfo event={event} onClose={() => undefined} />);
    expect(screen.getByRole("heading", { name: "Memory set" })).toBeInTheDocument();
    expect(screen.getByText("Name")).toBeInTheDocument();
    expect(screen.queryByText("Slot name")).toBeNull();
    expect(screen.getByText("Value")).toBeInTheDocument();
  });
});
